function.arguments:
{"query":"WITH wins AS (
  SELECT home_abbr AS abbr, COUNT(*) AS w FROM games WHERE home_pts > away_pts GROUP BY home_abbr
  UNION ALL
  SELECT away_abbr AS abbr, COUNT(*) FROM games WHERE away_pts > home_pts GROUP BY away_abbr
)
SELECT abbr, SUM(w) AS wins FROM wins GROUP BY abbr ORDER BY wins DESC LIMIT 5"}

